sources.entry:
import pricing_routes

def compute(value):
    if value % 2 == 0:
        return pricing_routes.primary(value)
    return pricing_routes.secondary(value)

sources.pricing_routes:
import calibration

def primary(value):
    return calibration.offset(value + 25) * 2

def secondary(value):
    return calibration.offset(value - 21) + 14

